11	    // Properties shared between all consumers:
12	    private static final int STARTING_SUSTENANCE_LEVEL = 20;
13	    private static final double NEW_DISEASE = 0.0005;
14	    private static final double NIGHT_PREY_MISS_PROBABILITY = 0.5;
