39	    public Consumer(Field field, Location location, List<Class<?>> prey, int consumptionWorth,
40	                    double breedingProbability, int maxBirthsAtOnce, int maxAge, int breedingAge,
41	                    int maxSustenanceLevel, boolean canEatCarcass, boolean primaryConsumer)
