160	     * @param randomAge If true, the age is random, otherwise it's 0.
161	     */
162	    protected void setStartingAge(boolean randomAge)
163	    {
164	        if (randomAge) currentAge = rand.nextInt(maxAge);
165	        else           currentAge = 0;
166	    }
