170	     * New births will be made into free adjacent locations.
171	     *
172	     * @param newConsumers A list to return newly born consumers.
173	     */
174	    private void giveBirth(List<Actor> newConsumers)
175	    {
176	        if (!checkForValidMate()) return;
177	
178	        Field field = getField();
179	        List<Location> free = field.getFreeAdjacentLocations(getLocation());
180	
181	        int births = breed();
182	        for (int b = 0; b < births && free.size() > 0; b++)
