217	     */
218	    private int breed()
219	    {
220	        int births = 0;
221	
222	        boolean willBreed = rand.nextDouble() <= getBreedingProbability();
223	
224	        if (canBreed() && willBreed)
225	            births = rand.nextInt(getMaxBirthsAtOnce()) + 1;
226	
227	        return births;
228	    }
