249	     *
250	     * @return Where food was found, or null if it wasn't.
251	     */
252	    private Location findFood()
253	    {
254	        Field field = getField();
255	
256	        for (Location where : field.adjacentLocations(getLocation()))
257	        {
258	            Object object = field.getObjectAt(where);
259	
260	            for (Class<?> preyClass : prey)
261	            {
262	                if (preyClass.isInstance(object))
263	                {
264	                    Actor actor = (Actor) object;
265	                    if (actor.getIsAlive())
266	                    {
267	                        boolean canHit = !TimeSystem.isNightTime()
268	                                      || rand.nextDouble() <= 1.0 - NIGHT_PREY_MISS_PROBABILITY;
269	                        if (canHit)
270	                            return eat(actor);
271	                    }
272	                }
273	            }
274	
275	            if (object instanceof Carcass carcass && canEatCarcass)
276	            {
277	                if (carcass.isDiseased())
278	                {
279	                    disease = giveDisease();
280	                }
281	                sustenanceLevel += carcass.getConsumptionWorth();
282	                carcass.setDead();
283	                return where;
284	            }
285	        }
286	
287	        return null;
288	    }
