298	     * @param actor The actor who is to be eaten.
299	     */
300	    private Location eat(Actor actor)
301	    {
302	        Location location = actor.getLocation();
303	        int actorConsumptionWorth = actor.getConsumptionWorth();
304	        if (actor.becomeCarcass())
305	        {
306	            actor.setDead();
307	            if ((sustenanceLevel + actorConsumptionWorth) > maxSustenanceLevel)
308	            {
309	                int foodLeft = (sustenanceLevel + consumptionWorth) - maxSustenanceLevel;
310	                sustenanceLevel = this.maxSustenanceLevel;
311	                newCarcass = new Carcass(getField(), location, foodLeft);
312	                ifCarcass = true;
313	                return getLocation();
314	            }
315	        }
316	        if (sustenanceLevel + actorConsumptionWorth <= maxSustenanceLevel)
317	        {
318	            sustenanceLevel += actorConsumptionWorth;
319	            return location;
320	        }
321	        return null;
322	    }
323	}
